      "name": "Matrix.det_mul_comm",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Determinant.Basic",
      "kind": "theorem",
      "type": "∀ {m : Type u_1} [inst : DecidableEq m] [inst_1 : Fintype m] {R : Type v} [inst_2 : CommRing R] (M N : Matrix m m R),\n  (M * N).det = (N * M).det"
    },
    {
      "name": "Matrix.det_transpose",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Determinant.Basic",
      "kind": "theorem",
      "type": "∀ {n : Type u_2} [inst : DecidableEq n] [inst_1 : Fintype n] {R : Type v} [inst_2 : CommRing R] (M : Matrix n n R),\n  M.transpose.det = M.det"
    },
    {
      "name": "Matrix.det_mul",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Determinant.Basic",
      "kind": "theorem",
      "type": "∀ {n : Type u_2} [inst : DecidableEq n] [inst_1 : Fintype n] {R : Type v} [inst_2 : CommRing R] (M N : Matrix n n R),\n  (M * N).det = M.det * N.det"
    },
    {
      "name": "Matrix.detMonoidHom",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Determinant.Basic",
      "kind": "definition",
      "type": "{n : Type u_2} →\n  [inst : DecidableEq n] → [inst_1 : Fintype n] → {R : Type v} → [inst_2 : CommRing R] → Matrix n n R →* R"
    },
    {
      "name": "LinearMap.det_prodMap",
      "module_name": "Mathlib.LinearAlgebra.Determinant",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {M : Type u_2} [inst_1 : AddCommGroup M] [inst_2 : Module R M] {M' : Type u_3}\n  [inst_3 : AddCommGroup M'] [inst_4 : Module R M'] [Module.Free R M] [Module.Free R M'] [Module.Finite R M]\n  [Module.Finite R M'] (f : Module.End R M) (f' : Module.End R M'),\n  LinearMap.det (LinearMap.prodMap f f') = LinearMap.det f * LinearMap.det f'"
    }
  ]
}
